-- Run once against the dedicated Complyra PostgreSQL database (for example, Neon).
-- The application connects with a least-privilege database role.
CREATE TABLE IF NOT EXISTS complyra_kv (
  record_key TEXT PRIMARY KEY,
  payload TEXT NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Payloads are authenticated AES-256-GCM ciphertext generated by the application.
-- Preserve DATA_ENCRYPTION_KEY in a secret manager and use encrypted, tested backups.
